    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The proofing flow must be tested with mismatched data to ensure the error messages do not reveal whether specific attributes matched."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "The IAL2 proofing process must be executed to verify that core attributes are validated against authoritative sources or via digital signatures."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "Successful IAL2 proofing must be tested to verify that a notification is sent to the validated address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The system configuration and code must be reviewed to confirm that knowledge-based verification is not implemented or enabled for company representatives."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The authentication configuration and code must be reviewed to ensure email is not used as an out-of-band authentication factor."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "The system must be tested with SMS codes submitted after 5 minutes to verify they are rejected, and before 5 minutes to verify they are accepted."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "The same SMS code must be submitted twice within its validity period to verify that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "The system must be tested to verify that generating a new SMS code does not reset the failed authentication count."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "Passwords with various compositions (e.g., all lowercase, no special characters) must be tested to verify that only length and blocklist checks are enforced."
    }
  ]
}

