{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik sonlandırılması, sistem üzerinde süre ve koşul simülasyonu yapılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediği, olaylar tetiklenerek ve kayıtlar incelenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damgalarının UTC cinsinden ve doğru ayrıntı düzeyinde kaydedildiği, sistem saatleri ve kayıtlar üzerinden test edilerek doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme denemelerinin algılanması ve uyarı mekanizmasının çalışması, saldırı senaryolarıyla test edilmelidir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Parola ve tek kullanımlık kodların ekranda gizlenip gizlenmediği, kullanıcı girişi sırasında gözlemlenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolan oturumlarda yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı test edilmelidir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüğü korunan protokollerle (ör. TLS) gerçekleştiği, ağ trafiği analizi ve bağlantı testleriyle doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz, bozuk veya beklenmedik girdilerin sistemin reddetmesi ve hata üretmesi, çeşitli girdi senaryolarıyla test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi vermesi ve ayrıntılı logların yetkili personele özel olarak kaydedilmesi, hata senaryolarıyla test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu yaklaşırken uyarı gösterilmesi, taslak kaydı ve yeniden doğrulama sonrası kaldığı yerden devam etme akışı test edilmelidir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmadığı, bot eşiği aşıldığında etkileşimsiz kanıt istendiği ve gerekirse WCAG uyumlu nesne tanıma sorgusu gösterildiği test edilmelidir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzası doğrulanan bildirimle kabul edilmesi, belirsiz durumlarda bekleme ve sorgulama mekanizması test edilmelidir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirteçlerinde oturumun sınırlı kipte açılması ve kişisel verilerin gizlenmesi test edilmelidir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulanması, bildirim gönderimi ve ele geçirme kanıtında zorunlu değişiklik test edilmelidir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adım için kabul edilmesi, eski/ileri adımların reddedilmesi ve tek kullanımlık olması test edilmelidir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Belirli sayıda başarısız denemeden sonra doğrulayıcının devre dışı bırakılması, hesap kurtarma gerekliliği ve sayaç sıfırlama test edilmelidir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 ve AAL3 oturumlarında hareketsizlik sonrası farklı yeniden kimlik doğrulama akışlarının (parola vs. e-Devlet) ve oturum sırrı silinmesinin test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılması, kullanıcıya bildirim ve SIEM'e olay iletimi test edilmelidir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, içerik imzası ve boyut/sayı sınırlarının denetlenmesi, geçersiz dosyaların reddedilmesi ve ret nedeninin bildirilmesi test edilmelidir."
    }
  ]
}

{
