      "priority": "Yüksek",
      "preconditions": "A communication session is established. The OBU has initiated termination. The trackside is configured to never send an acknowledgement. The defined number of repetitions from SUBSET-026 Appendix A.3.1 is known (e.g., N).",
      "test_inputs": "Fixed waiting time and defined number of repetitions from SUBSET-026 Appendix A.3.1.",
      "assumptions": "The defined number of repetitions is N. The fixed waiting time is T.",
      "steps": [
        {
          "no": 1,
          "action": "The OBU sends the 'Termination of communication session' message (1st send).",
          "expected": "Message sent."
