          "no": 2,
          "action": "Wait for time T. No acknowledgement received.",
          "expected": "The OBU repeats the message (1st repetition)."
        },
        {
          "no": 3,
          "action": "Repeat the wait and repetition process until the defined number of repetitions (N) has been reached.",
          "expected": "The OBU has sent the message a total of N+1 times (initial + N repetitions)."
        },
        {
          "no": 4,
          "action": "Wait for the fixed waiting time T after the last sending (the Nth repetition). No acknowledgement is received.",
          "expected": "The OBU considers the communication session terminated. No further 'Termination of communication session' messages are sent."
        }
      ]
    },
