        "ETC-076"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Level 1, mode FS, LS or AD; linking information stored (including the main signal balise group BGa); loop infill area information stored and a communication session with the loop infill unit established.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Level 1, loop infill session established; the train passes and reads the next main signal balise group indicated in the order.",
          "expected": "The OBU registers the reading of the main signal balise group."
        },
        {
          "no": 2,
          "action": "After reading the main signal balise group, the OBU receives new infill information from the loop referring to that balise group.",
          "expected": "The OBU ignores the infill information (its infill MA is not applied: no trip, no emergency brake)."
        }
      ]
    },
    {
      "id": "TC-ETC-076-02",
      "title": "OBU ignores loop infill after detecting missed next main signal balise group",
      "covers": [
        "ETC-076"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Level 1, mode FS, LS or AD; linking information stored (including the main signal balise group BGa with reaction 'no reaction'); loop infill area information stored and a communication session with the loop infill unit established.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Level 1, loop infill session established; the train's min safe antenna position passes the last possible location of the next main signal balise group (plus detection margin) without detecting it.",
          "expected": "The OBU detects the balise group as missed."
        },
        {
          "no": 2,
          "action": "After detecting the missed balise group, the OBU receives new infill information from the loop referring to that balise group.",
          "expected": "The OBU ignores the infill information (its infill MA is not applied: no trip, no emergency brake)."
        }
      ]
    }
  ]
}

