      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is in a mode where Level Crossing information is processed (e.g., FS, OS, LS, AD, SM). A Level Crossing (LX) with identity 'LX-001' is already stored in the OBU memory with specific parameters (e.g., protected status, start location, length).",
      "test_inputs": "A new Level Crossing information message with identity 'LX-001' but different parameters (e.g., different start location or protection status) is received by the OBU.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Verify the stored Level Crossing information for identity 'LX-001' before receiving the new message.",
          "expected": "The OBU holds the initial Level Crossing parameters for 'LX-001'."
        },
        {
          "no": 2,
          "action": "Transmit a new Level Crossing information message to the OBU with identity 'LX-001' and modified parameters (e.g., changed start location or protection status).",
          "expected": "The OBU accepts the new information."
        },
        {
          "no": 3,
          "action": "Inspect the stored Level Crossing information for identity 'LX-001' in the OBU.",
          "expected": "The stored Level Crossing information for 'LX-001' is updated to reflect the parameters of the newly received message. The old parameters are no longer present."
        }
      ]
    },
    {
      "id": "TC-ETC-109-02",
      "title": "Independence of Level Crossing information with different identities",
      "covers": [
        "ETC-109"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "The OBU is in a mode where Level Crossing information is processed. Two distinct Level Crossings, 'LX-001' and 'LX-002', are already stored in the OBU memory.",
      "test_inputs": "A new Level Crossing information message with identity 'LX-001' and modified parameters is received.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Verify the stored Level Crossing information for both 'LX-001' and 'LX-002' before the test.",
          "expected": "Both 'LX-001' and 'LX-002' are stored with their initial parameters."
        },
        {
          "no": 2,
          "action": "Transmit a new Level Crossing information message to the OBU with identity 'LX-001' and modified parameters.",
          "expected": "The OBU accepts the new information for 'LX-001'."
        },
        {
          "no": 3,
          "action": "Inspect the stored Level Crossing information for 'LX-001' and 'LX-002' in the OBU.",
          "expected": "The stored information for 'LX-001' is updated to the new parameters. The stored information for 'LX-002' remains unchanged, confirming that the replacement of 'LX-001' did not affect 'LX-002'."
