{
  "test_cases": [
    {
      "id": "TC-KDH-024-01",
      "title": "Generating a new SMS code does not reset the failed authentication count",
      "covers": [
        "KDH-024"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active company representative account at AAL2 with SMS bound as the second factor. The account has a non-zero failed authentication count (e.g., 1 failed attempt recorded).",
      "test_inputs": "",
      "assumptions": "The system allows the tester to observe the current failed authentication count or the state of the account regarding lockout thresholds.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate an authentication attempt and fail the SMS code verification once to establish a failed count of 1.",
          "expected": "The system records the failed attempt. The account is not locked."
        },
        {
          "no": 2,
          "action": "Request a new SMS one-time code for the same account (e.g., by clicking 'Resend Code' or starting a new login flow that triggers code generation).",
          "expected": "A new SMS code is sent to the registered telephone number."
        },
        {
          "no": 3,
          "action": "Check the failed authentication count for the account.",
          "expected": "The failed authentication count remains at 1. It has not been reset to 0 by the generation of the new code."
        }
      ]
    },
    {
      "id": "TC-KDH-024-02",
      "title": "Failed count persists across multiple code generations before lockout",
      "covers": [
        "KDH-024"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "An active company representative account at AAL2 with SMS bound as the second factor. The maximum allowed consecutive failed attempts is known (e.g., 5).",
      "test_inputs": "",
      "assumptions": "The maximum number of consecutive failed attempts before lockout is 5.",
      "steps": [
        {
          "no": 1,
          "action": "Perform 4 failed authentication attempts using incorrect SMS codes, generating a new code after each failure.",
          "expected": "After the 4th failure, the failed authentication count is 4. The account is not yet locked."
        },
        {
          "no": 2,
          "action": "Request a new SMS code (5th code generation) and attempt authentication with an incorrect code.",
          "expected": "The 5th failed attempt is recorded. The failed authentication count reaches the maximum limit (5)."
        },
        {
          "no": 3,
          "action": "Request a new SMS code (6th code generation) and attempt authentication.",
          "expected": "The system enforces the lockout or restriction based on the 5th failure. The generation of the 6th code does not reset the count to allow further attempts beyond the limit."
        }
      ]
    }
  ]
}

